#!/usr/bin/env python3
"""Synchronize the CFS material catalog from a Creality material_database.json.

Only the marked catalog region of src/data/cfs_data.c is generated.
Everything else remains hand-maintained.
No external Python dependencies are required.
"""

from __future__ import annotations

import argparse
import difflib
import json
import os
from pathlib import Path
import re
import stat
import sys
import tempfile

REPO_ROOT = Path(__file__).resolve().parents[1]
C_REL = Path("src/data/cfs_data.c")
C_BEGIN = "// BEGIN GENERATED MATERIAL CATALOG"
C_END = "// END GENERATED MATERIAL CATALOG"
BRANDS = {"Generic": "CfsBrandGeneric", "Creality": "CfsBrandCreality", "eSUN": "CfsBrandESUN"}


class CatalogError(ValueError):
    """The input JSON or generated-region markers are invalid."""


def _pairs_no_duplicates(pairs: list[tuple[str, object]]) -> dict:
    result = {}
    for key, value in pairs:
        if key in result:
            raise CatalogError(f"duplicate JSON object key: {key!r}")
        result[key] = value
    return result


def _not_json_constant(value: str) -> None:
    raise CatalogError(f"invalid JSON numeric constant: {value}")


def load_catalog(json_path: Path) -> list[dict]:
    with json_path.open(encoding="utf-8") as f:
        source = json.load(
            f, object_pairs_hook=_pairs_no_duplicates, parse_constant=_not_json_constant
        )
    if not isinstance(source, dict) or type(source.get("code")) is not int or source["code"] != 0:
        raise CatalogError("expected a successful response with 'code': 0")
    result = source.get("result")
    if not isinstance(result, dict) or not isinstance(result.get("list"), list):
        raise CatalogError("missing result.list array")
    records = result["list"]
    if not records:
        raise CatalogError("result.list must not be empty")
    if type(result.get("count")) is not int or result["count"] != len(records):
        raise CatalogError("result.count does not match result.list length")

    materials = []
    used_ids = set()
    for position, record in enumerate(records):
        prefix = f"result.list[{position}]"
        if not isinstance(record, dict) or not isinstance(record.get("base"), dict):
            raise CatalogError(f"{prefix}: missing base object")
        base = record["base"]
        ident = base.get("id")
        if not isinstance(ident, str) or re.fullmatch(r"[0-9A-Z]{5}", ident) is None:
            raise CatalogError(f"{prefix}.base.id: expected five uppercase alphanumeric characters")
        if ident in used_ids:
            raise CatalogError(f"duplicate material id {ident}")
        used_ids.add(ident)
        brand = base.get("brand")
        if brand not in BRANDS:
            raise CatalogError(
                f"{prefix} ({ident}): unsupported brand {brand!r}; "
                "add an explicit CfsBrand enum and vendor mapping before generating"
            )
        for field in ("name", "meterialType"):
            value = base.get(field)
            if not isinstance(value, str) or not value.strip() or "\x00" in value:
                raise CatalogError(f"{prefix} ({ident}): invalid base.{field}")
        for field in ("minTemp", "maxTemp"):
            value = base.get(field)
            if type(value) is not int or not (0 <= value <= 65535):
                raise CatalogError(f"{prefix} ({ident}): base.{field} must be a uint16 temperature")
        if base["minTemp"] > base["maxTemp"]:
            raise CatalogError(f"{prefix} ({ident}): minimum temperature exceeds maximum")

        materials.append(base)
    return sorted(materials, key=lambda row: row["id"])


def c_string(value: str) -> str:
    """Escape a UTF-8 string as a portable ASCII-only C literal."""
    output = []
    for code in value.encode("utf-8"):
        if code in (34, 92):
            output.append("\\" + chr(code))
        elif 32 <= code <= 126:
            output.append(chr(code))
        else:
            output.append(f"\\{code:03o}")
    return '"' + "".join(output) + '"'


def render_c(materials: list[dict]) -> str:
    lines = [
        "// Generated by scripts/update_material_catalog.py. Do not edit this region.",
        "// Source: material_database.json result.list[*].base (not kvParam).",
        "static const CfsFilamentInfo cfs_catalog[] = {",
    ]
    for base in materials:
        lines.append(
            "    {" + ", ".join(
                (
                    c_string(base["id"]),
                    BRANDS[base["brand"]],
                    c_string(base["meterialType"]),
                    c_string(base["name"]),
                    str(base["minTemp"]),
                    str(base["maxTemp"]),
                )
            ) + "},"
        )
    lines.append("};")
    return "\n".join(lines)


def replace_region(original: str, begin: str, end: str, generated: str) -> str:
    for marker in (begin, end):
        if original.count(marker) != 1:
            raise CatalogError(f"expected exactly one marker {marker!r}")
    start = original.index(begin) + len(begin)
    stop = original.index(end)
    if start >= stop:
        raise CatalogError(f"incorrect order of {begin!r} and {end!r}")
    if not original[start:stop].startswith("\n") or not original[start:stop].endswith("\n"):
        raise CatalogError(f"generated region {begin!r} must be surrounded by newlines")
    return original[:start] + "\n" + generated + "\n" + original[stop:]


def atomic_write(path: Path, content: str) -> None:
    fd, temp_name = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=path.parent)
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as f:
            f.write(content)
        os.chmod(temp_name, stat.S_IMODE(path.stat().st_mode))
        os.replace(temp_name, path)
    finally:
        if os.path.exists(temp_name):
            os.unlink(temp_name)


def run(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("json", type=Path, help="the external material_database.json source")
    parser.add_argument("--repo-root", type=Path, default=REPO_ROOT, help=argparse.SUPPRESS)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--check", action="store_true", help="report drift and exit 1, never write")
    mode.add_argument("--dry-run", action="store_true", help="show diffs without writing")
    args = parser.parse_args(argv)

    try:
        materials = load_catalog(args.json)

        path = args.repo_root / C_REL
        old = path.read_text(encoding="utf-8")
        new = replace_region(old, C_BEGIN, C_END, render_c(materials))
    except (OSError, ValueError, KeyError, TypeError) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2

    print(f"Validated {len(materials)} materials.")
    changed = old != new
    if changed and (args.check or args.dry_run):
        print("".join(difflib.unified_diff(
            old.splitlines(keepends=True), new.splitlines(keepends=True),
            fromfile=str(path) + " (current)", tofile=str(path) + " (generated)",
        )), end="")
    elif changed:
        atomic_write(path, new)
        print(f"Updated {path}")
    else:
        print("Catalog already synchronized; no changes required.")

    if args.check and changed:
        print("Catalog drift: src/data/cfs_data.c needs regeneration.", file=sys.stderr)
        return 1
    if args.dry_run and changed:
        print("Dry run: src/data/cfs_data.c would be updated.")
    return 0


if __name__ == "__main__":
    sys.exit(run())
